/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Sealed traits and case classes for ADTs
 * - Variance annotations (covariant/contravariant)
 * - Option for null safety
 * - Either for error handling
 * - Type classes for extensible behavior
 * - Builder pattern with fluent interface
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import scala.util.matching.Regex

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }

  val values: Seq[TokenType] = Seq(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)

  def fromString(s: String): Option[TokenType] = values.find(_.value == s)
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
final class MutableTokenBatch private (
  private val _tokens: mutable.ListBuffer[Token],
  private var _processed: Boolean
) {
  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) {
      throw new IllegalStateException("Batch already processed")
    }
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def isProcessed: Boolean = _processed
}

object MutableTokenBatch {
  def apply(): MutableTokenBatch = new MutableTokenBatch(mutable.ListBuffer.empty, false)
}

// ============================================================================
// Type Classes for Tokenizable
// ============================================================================

/**
 * Type class for objects that can be converted to a token string.
 */
trait Tokenizable[A] {
  def toToken(a: A): String
}

object Tokenizable {
  def apply[A](implicit ev: Tokenizable[A]): Tokenizable[A] = ev

  implicit val stringTokenizable: Tokenizable[String] = (a: String) => a
  implicit val intTokenizable: Tokenizable[Int] = (a: Int) => a.toString
  implicit val longTokenizable: Tokenizable[Long] = (a: Long) => a.toString
  implicit val doubleTokenizable: Tokenizable[Double] = (a: Double) => a.toString
  implicit val bigDecimalTokenizable: Tokenizable[BigDecimal] = (a: BigDecimal) => a.toString()
}

/**
 * Type class for objects with a length.
 */
trait HasLength[A] {
  def length(a: A): Int
}

object HasLength {
  def apply[A](implicit ev: HasLength[A]): HasLength[A] = ev

  implicit val stringHasLength: HasLength[String] = (a: String) => a.length
  implicit def seqHasLength[T]: HasLength[Seq[T]] = (a: Seq[T]) => a.length
  implicit def arrayHasLength[T]: HasLength[Array[T]] = (a: Array[T]) => a.length
}

/**
 * Contravariant processor that consumes tokens.
 */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
final class TokenContainer[+A](items: Seq[A]) {
  private val _items: Vector[A] = items.toVector

  def getAll: Vector[A] = _items

  def mapTokens[B](func: A => B): Vector[B] = _items.map(func)
}

object TokenContainer {
  def apply[A](items: A*): TokenContainer[A] = new TokenContainer(items)
  def fromSeq[A](items: Seq[A]): TokenContainer[A] = new TokenContainer(items)
}

/**
 * Contravariant sink - can accept supertypes.
 */
final class TokenSink[-A] {
  private val _received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: A): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

object TokenSink {
  def apply[A](): TokenSink[A] = new TokenSink[A]
}

/**
 * Invariant handler - exact type matching required.
 */
final class BivariantHandler[A](private var _value: A) {
  def get: A = _value

  def set(value: A): Unit = {
    _value = value
  }

  def transform(func: A => A): A = {
    _value = func(_value)
    _value
  }
}

object BivariantHandler {
  def apply[A](default: A): BivariantHandler[A] = new BivariantHandler(default)
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[A] {
  /**
   * Convert value to token.
   */
  def tokenize(value: A): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/**
 * Tokenizer for string and bytes types.
 */
final class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s) => s
      case Right(bytes) => new String(bytes, encoding)
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }

  /**
   * Convenience method for tokenizing strings directly.
   */
  def tokenizeString(value: String): Token = tokenize(Left(value))

  /**
   * Convenience method for tokenizing bytes directly.
   */
  def tokenizeBytes(value: Array[Byte]): Token = tokenize(Right(value))
}

object StringTokenizer {
  def apply(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
  ): StringTokenizer = new StringTokenizer(encoding, normalizer)
}

/**
 * Tokenizer for numeric types with precision handling.
 */
final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Either[Int, Long], Either[Double, BigDecimal]]] {

  override def tokenize(value: Either[Either[Int, Long], Either[Double, BigDecimal]]): Token = {
    val (strValue, typeName) = value match {
      case Left(Left(i)) => (i.toString, "Int")
      case Left(Right(l)) => (l.toString, "Long")
      case Right(Left(d)) => (s"%.${precision}f".format(d), "Double")
      case Right(Right(bd)) => (bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString(), "BigDecimal")
    }
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> typeName))
  }

  /**
   * Convenience method for tokenizing Int values.
   */
  def tokenizeInt(value: Int): Token = tokenize(Left(Left(value)))

  /**
   * Convenience method for tokenizing Long values.
   */
  def tokenizeLong(value: Long): Token = tokenize(Left(Right(value)))

  /**
   * Convenience method for tokenizing Double values.
   */
  def tokenizeDouble(value: Double): Token = tokenize(Right(Left(value)))

  /**
   * Convenience method for tokenizing BigDecimal values.
   */
  def tokenizeBigDecimal(value: BigDecimal): Token = tokenize(Right(Right(value)))
}

object NumericTokenizer {
  def apply(precision: Int = 6, formatOptions: Map[String, Any] = Map.empty): NumericTokenizer =
    new NumericTokenizer(precision, formatOptions)
}

/**
 * Tokenizer for date/time types.
 */
final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {
  import TemporalTokenizer._

  override def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatted = value match {
      case Left(dateTime) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(IsoFormat)
        dateTime.format(fmt)
      case Right(date) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DateFormat)
        date.format(fmt)
    }
    Token(formatted, TokenType.TEMPORAL)
  }

  /**
   * Convenience method for tokenizing LocalDateTime values.
   */
  def tokenizeDateTime(value: LocalDateTime): Token = tokenize(Left(value))

  /**
   * Convenience method for tokenizing LocalDate values.
   */
  def tokenizeDate(value: LocalDate): Token = tokenize(Right(value))
}

object TemporalTokenizer {
  val IsoFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  val DateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def apply(formatStr: Option[String] = None): TemporalTokenizer = new TemporalTokenizer(formatStr)
}

// ============================================================================
// Advanced: Union Types via Sealed Trait
// ============================================================================

/**
 * Represents all tokenizable values for UniversalTokenizer.
 */
sealed trait TokenizableValue

object TokenizableValue {
  final case class StringValue(value: String) extends TokenizableValue
  final case class BytesValue(value: Array[Byte]) extends TokenizableValue
  final case class IntValue(value: Int) extends TokenizableValue
  final case class LongValue(value: Long) extends TokenizableValue
  final case class DoubleValue(value: Double) extends TokenizableValue
  final case class BigDecimalValue(value: BigDecimal) extends TokenizableValue
  final case class DateTimeValue(value: LocalDateTime) extends TokenizableValue
  final case class DateValue(value: LocalDate) extends TokenizableValue
  final case class CustomTokenizable(toToken: () => String) extends TokenizableValue
  case object NullValue extends TokenizableValue
}

/**
 * Tokenizer that handles multiple types with pattern matching.
 */
final class UniversalTokenizer {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  import TokenizableValue._

  def tokenize(value: TokenizableValue): Token = value match {
    case NullValue => Token("NULL", TokenType.NULL)
    case CustomTokenizable(toTokenFn) => Token(toTokenFn(), TokenType.STRUCTURED)
    case StringValue(s) => stringTokenizer.tokenizeString(s)
    case BytesValue(b) => stringTokenizer.tokenizeBytes(b)
    case IntValue(i) => numericTokenizer.tokenizeInt(i)
    case LongValue(l) => numericTokenizer.tokenizeLong(l)
    case DoubleValue(d) => numericTokenizer.tokenizeDouble(d)
    case BigDecimalValue(bd) => numericTokenizer.tokenizeBigDecimal(bd)
    case DateTimeValue(dt) => temporalTokenizer.tokenizeDateTime(dt)
    case DateValue(d) => temporalTokenizer.tokenizeDate(d)
  }

  /**
   * Tokenize any value with fallback to string conversion.
   */
  def tokenizeAny(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case s: String => stringTokenizer.tokenizeString(s)
    case b: Array[Byte] => stringTokenizer.tokenizeBytes(b)
    case i: Int => numericTokenizer.tokenizeInt(i)
    case l: Long => numericTokenizer.tokenizeLong(l)
    case d: Double => numericTokenizer.tokenizeDouble(d)
    case bd: BigDecimal => numericTokenizer.tokenizeBigDecimal(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenizeDateTime(dt)
    case d: LocalDate => temporalTokenizer.tokenizeDate(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 */
final class TokenRegistry[A] {
  private val _registry: mutable.Map[String, TokenContainer[A]] = mutable.Map.empty
  private val _handlers: mutable.ListBuffer[A => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[A]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: A => Option[Token]): Unit = {
    _handlers += handler
  }

  /**
   * Process all items in a container through all handlers.
   */
  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.iterator
            .map(handler => handler(item))
            .find(_.isDefined)
            .flatten
        }.toList
    }
  }
}

object TokenRegistry {
  def apply[A](): TokenRegistry[A] = new TokenRegistry[A]
}

// ============================================================================
// Functor and Monad Abstractions
// ============================================================================

/**
 * Functor for tokens - provides map operation.
 */
class TokenFunctor[A](protected val _value: A) {
  def map[B](func: A => B): TokenFunctor[B] = new TokenFunctor(func(_value))

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] = func(_value)

  def getOrElse(default: => A): A = Option(_value).getOrElse(default)

  def get: A = _value
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = new TokenFunctor(value)
}

/**
 * Extended monad operations.
 */
class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  /**
   * Applicative apply.
   */
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(this._value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)

  def apply[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Represents JSON values using a sealed trait hierarchy.
 */
sealed trait JsonValue {
  def asString: Option[String] = this match {
    case JsonString(s) => Some(s)
    case _ => None
  }

  def asNumber: Option[BigDecimal] = this match {
    case JsonNumber(n) => Some(n)
    case _ => None
  }

  def asBoolean: Option[Boolean] = this match {
    case JsonBoolean(b) => Some(b)
    case _ => None
  }

  def asArray: Option[Vector[JsonValue]] = this match {
    case JsonArray(arr) => Some(arr)
    case _ => None
  }

  def asObject: Option[Map[String, JsonValue]] = this match {
    case JsonObject(obj) => Some(obj)
    case _ => None
  }
}

final case class JsonString(value: String) extends JsonValue
final case class JsonNumber(value: BigDecimal) extends JsonValue
final case class JsonBoolean(value: Boolean) extends JsonValue
final case class JsonArray(value: Vector[JsonValue]) extends JsonValue
final case class JsonObject(value: Map[String, JsonValue]) extends JsonValue
case object JsonNull extends JsonValue

/**
 * Tokenizer for JSON structures with recursive types.
 */
final class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) toJsonStringPretty(value, 0) else toJsonString(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /**
   * Extract and tokenize a value at a JSON path.
   */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    extractPath(value, parts).map(tokenize)
  }

  private def extractPath(value: JsonValue, parts: List[String]): Option[JsonValue] = {
    parts match {
      case Nil => Some(value)
      case head :: tail =>
        value match {
          case JsonObject(obj) =>
            obj.get(head).flatMap(extractPath(_, tail))
          case JsonArray(arr) =>
            Try(head.toInt).toOption.flatMap { idx =>
              if (idx >= 0 && idx < arr.size) extractPath(arr(idx), tail)
              else None
            }
          case _ => None
        }
    }
  }

  private def toJsonString(value: JsonValue): String = value match {
    case JsonString(s) => s""""${escapeString(s)}""""
    case JsonNumber(n) => n.toString()
    case JsonBoolean(b) => b.toString
    case JsonNull => "null"
    case JsonArray(arr) => arr.map(toJsonString).mkString("[", ", ", "]")
    case JsonObject(obj) =>
      obj.map { case (k, v) => s""""${escapeString(k)}": ${toJsonString(v)}""" }
        .mkString("{", ", ", "}")
  }

  private def toJsonStringPretty(value: JsonValue, indent: Int): String = {
    val spaces = "  " * indent
    val innerSpaces = "  " * (indent + 1)

    value match {
      case JsonString(s) => s""""${escapeString(s)}""""
      case JsonNumber(n) => n.toString()
      case JsonBoolean(b) => b.toString
      case JsonNull => "null"
      case JsonArray(arr) if arr.isEmpty => "[]"
      case JsonArray(arr) =>
        arr.map(v => innerSpaces + toJsonStringPretty(v, indent + 1))
          .mkString("[\n", ",\n", s"\n$spaces]")
      case JsonObject(obj) if obj.isEmpty => "{}"
      case JsonObject(obj) =>
        obj.map { case (k, v) =>
          s"""$innerSpaces"${escapeString(k)}": ${toJsonStringPretty(v, indent + 1)}"""
        }.mkString("{\n", ",\n", s"\n$spaces}")
    }
  }

  private def escapeString(s: String): String = {
    s.flatMap {
      case '"' => "\\\""
      case '\\' => "\\\\"
      case '\b' => "\\b"
      case '\f' => "\\f"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c if c < 32 => f"\\u${c.toInt}%04x"
      case c => c.toString
    }
  }
}

object JsonTokenizer {
  def apply(pretty: Boolean = false): JsonTokenizer = new JsonTokenizer(pretty)
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 *
 * This is a fundamental tokenization operation used in NLP and text processing.
 */
final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var currentPos = 0
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      currentPos = end

      processToken(word).map(processed => (processed, start, end))
    }.toList
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = tokenize(text).length
}

object WhitespaceTokenizer {
  def apply(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ): WhitespaceTokenizer = new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 */
final class TokenizerBuilder[A] private (
  normalizers: Vector[String => String],
  validators: Vector[A => Boolean],
  metadata: Map[String, Any]
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators, metadata ++ entries.toMap)

  /**
   * Build the final tokenizer function.
   */
  def build(): A => Either[String, Token] = { (value: A) =>
    val validationResult = validators.find(v => !v(value))
    validationResult match {
      case Some(_) => Left(s"Validation failed for $value")
      case None =>
        var strValue = value.toString
        normalizers.foreach { normalizer =>
          strValue = normalizer(strValue)
        }
        Right(Token(strValue, TokenType.STRING, metadata))
    }
  }

  /**
   * Build tokenizer that throws on validation failure (matches Python behavior).
   */
  def buildUnsafe(): A => Token = { (value: A) =>
    build()(value) match {
      case Right(token) => token
      case Left(error) => throw new IllegalArgumentException(error)
    }
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] = new TokenizerBuilder(Vector.empty, Vector.empty, Map.empty)
}

// ============================================================================
// Companion object with convenience methods
// ============================================================================

/**
 * Main entry point providing convenience methods matching Python module-level functions.
 */
object Tokenizer {
  private val universalTokenizer = UniversalTokenizer()

  /**
   * Tokenize any value using the universal tokenizer.
   */
  def tokenize(value: Any): Token = universalTokenizer.tokenizeAny(value)

  /**
   * Batch tokenize multiple values.
   */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Convert a value to a token string using a type class instance.
   */
  def toToken[A: Tokenizable](a: A): String = Tokenizable[A].toToken(a)

  /**
   * Create a new token with additional metadata.
   */
  def withMetadata(token: Token, entries: (String, Any)*): Token =
    token.withMetadata(entries: _*)
}
